import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.e4u2V5E7.js";const p=JSON.parse('{"title":"Ai Engineering","description":"Ai Engineering reference documentation","frontmatter":{"title":"Ai Engineering","description":"Ai Engineering reference documentation"},"headers":[],"relativePath":"knowledge/ai-engineering.md","filePath":"knowledge/ai-engineering.md","lastUpdated":1784485118000}'),i={name:"knowledge/ai-engineering.md"};function o(s,e,l,c,d,g){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="ai-engineering" tabindex="-1">Ai Engineering <a class="header-anchor" href="#ai-engineering" aria-label="Permalink to &quot;Ai Engineering&quot;">​</a></h1><h1 id="ai-engineering-—-knowledge-base" tabindex="-1">AI Engineering — Knowledge Base <a class="header-anchor" href="#ai-engineering-—-knowledge-base" aria-label="Permalink to &quot;AI Engineering — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>AI Engineering covers the integration of Large Language Models (LLMs) into applications. This knowledge base addresses LLM API patterns, streaming, function calling, guardrails, evaluation, cost management, and error handling for building reliable AI-powered features in Next.js applications.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="llm-api-integration" tabindex="-1">LLM API Integration <a class="header-anchor" href="#llm-api-integration" aria-label="Permalink to &quot;LLM API Integration&quot;">​</a></h3><p><strong>Completion APIs</strong> — Send prompts, receive text responses. The fundamental interaction pattern with models like GPT-4, Claude, Gemini.</p><p><strong>Chat APIs</strong> — Structured conversation with system, user, and assistant messages. Maintains context through message history.</p><p><strong>Streaming</strong> — Token-by-token response delivery via Server-Sent Events (SSE). Reduces perceived latency and enables real-time display.</p><p><strong>Embeddings</strong> — Convert text to numerical vectors for semantic search, clustering, and similarity comparison.</p><h3 id="prompt-architecture" tabindex="-1">Prompt Architecture <a class="header-anchor" href="#prompt-architecture" aria-label="Permalink to &quot;Prompt Architecture&quot;">​</a></h3><p><strong>System prompts</strong> — Define model behavior, personality, and constraints. Set once per conversation. <strong>User prompts</strong> — The actual query or instruction from the user. <strong>Assistant prompts</strong> — Model responses, either pre-filled or from previous turns.</p><h3 id="function-calling-tool-use" tabindex="-1">Function Calling / Tool Use <a class="header-anchor" href="#function-calling-tool-use" aria-label="Permalink to &quot;Function Calling / Tool Use&quot;">​</a></h3><p>LLMs can invoke external functions by generating structured JSON arguments. The model decides which function to call based on the prompt and available tools.</p><p><strong>Flow:</strong></p><ol><li>Define available functions with JSON Schema parameters</li><li>Send prompt with function definitions</li><li>Model responds with function call request</li><li>Execute function, return result to model</li><li>Model generates final response incorporating function results</li></ol><h3 id="guardrails" tabindex="-1">Guardrails <a class="header-anchor" href="#guardrails" aria-label="Permalink to &quot;Guardrails&quot;">​</a></h3><p>Safety and quality controls that constrain LLM behavior:</p><p><strong>Input guardrails</strong> — Validate, sanitize, and filter user inputs before sending to LLM <strong>Output guardrails</strong> — Validate LLM responses for correctness, safety, and format compliance <strong>Content moderation</strong> — Detect and block harmful, offensive, or inappropriate content</p><h3 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Evaluation&quot;">​</a></h3><p><strong>Automated metrics</strong> — Accuracy, relevance, format compliance, latency, and cost per request <strong>Human evaluation</strong> — Expert review of response quality, helpfulness, and safety <strong>A/B testing</strong> — Compare different prompts, models, or configurations with real users <strong>Regression testing</strong> — Ensure changes don&#39;t degrade existing functionality</p><h3 id="cost-management" tabindex="-1">Cost Management <a class="header-anchor" href="#cost-management" aria-label="Permalink to &quot;Cost Management&quot;">​</a></h3><p><strong>Token-based pricing</strong> — Most providers charge per input and output tokens <strong>Caching</strong> — Store and reuse responses for repeated queries <strong>Model tiering</strong> — Use cheaper models for simple tasks, expensive models for complex reasoning <strong>Rate limiting</strong> — Prevent abuse and control costs per user or per feature</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Stream all LLM responses</strong> — Use streaming for any user-facing LLM interaction; it reduces perceived latency and improves user experience dramatically</li><li><strong>Implement structured output</strong> — Use JSON mode or function calling to enforce response format; don&#39;t rely on free-form text parsing</li><li><strong>Add comprehensive error handling</strong> — LLM APIs fail with rate limits, timeouts, and model errors; implement retry logic with exponential backoff</li><li><strong>Cache responses aggressively</strong> — For deterministic queries, cache results with TTL; use semantic similarity for near-duplicate detection</li><li><strong>Validate all LLM outputs</strong> — Never trust LLM responses blindly; validate format, content, and business rules before using results</li><li><strong>Monitor costs per feature</strong> — Track token usage and costs for each AI feature; set alerts for unexpected cost increases</li><li><strong>Use system prompts to constrain behavior</strong> — Clearly define what the model should and shouldn&#39;t do; include output format instructions</li><li><strong>Test with diverse inputs</strong> — LLMs behave differently with various phrasings; test with edge cases, adversarial inputs, and multilingual queries</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Sending raw user input to LLM</strong> — User prompts may contain prompt injection attacks; sanitize and validate all inputs before sending</li><li><strong>Trusting LLM output without validation</strong> — LLMs hallucinate; always validate responses against business logic and data sources</li><li><strong>Using free-form text parsing</strong> — Parsing LLM output with regex is fragile; use function calling or JSON mode for structured data</li><li><strong>Ignoring rate limits</strong> — Not implementing retry logic causes feature failures; use exponential backoff and circuit breakers</li><li><strong>Storing API keys in client-side code</strong> — LLM API keys must only be used server-side; route all requests through API routes</li><li><strong>Over-relying on one model</strong> — Different tasks suit different models; build abstractions that allow model switching</li><li><strong>Skipping evaluation</strong> — Deploying AI features without measuring quality leads to silent degradation; establish baselines and monitor</li><li><strong>Not handling streaming errors</strong> — Stream interruptions happen; implement fallback to non-streaming on stream failure</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not setting max_tokens</strong> — Unbounded responses can be extremely expensive and slow; always set appropriate token limits</li><li><strong>Including too much context</strong> — Longer prompts cost more and may confuse the model; be concise and relevant</li><li><strong>Using GPT-4 for simple tasks</strong> — Classification, extraction, and simple transformations work well with cheaper models (GPT-4o-mini, Claude Haiku)</li><li><strong>Not handling model updates</strong> — Providers update models frequently; pin specific model versions or test thoroughly when updating</li><li><strong>Ignoring latency requirements</strong> — LLM responses take 1-10+ seconds; design UIs with loading states and streaming</li><li><strong>Missing content moderation</strong> — User-facing AI features must filter harmful content; use provider moderation APIs</li><li><strong>Not versioning prompts</strong> — Prompts are code; version them, track changes, and test modifications before deploying</li><li><strong>Forgetting about multilingual support</strong> — Test LLM features with Arabic and English inputs; model performance varies by language</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Recommended Approach</th></tr></thead><tbody><tr><td>Simple text classification</td><td>GPT-4o-mini with structured output</td></tr><tr><td>Complex reasoning task</td><td>GPT-4 or Claude Sonnet with chain-of-thought</td></tr><tr><td>Real-time chat</td><td>Streaming with conversation history management</td></tr><tr><td>Data extraction</td><td>Function calling with strict JSON schema</td></tr><tr><td>Content generation</td><td>System prompt + user context + streaming</td></tr><tr><td>Search/RAG</td><td>Embeddings for retrieval + LLM for answer generation</td></tr><tr><td>Cost-sensitive features</td><td>Model tiering + caching + token limits</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>OpenAI API Documentation: <a href="https://platform.openai.com/docs" target="_blank" rel="noreferrer">https://platform.openai.com/docs</a></li><li>Anthropic API Documentation: <a href="https://docs.anthropic.com/" target="_blank" rel="noreferrer">https://docs.anthropic.com/</a></li><li>Vercel AI SDK: <a href="https://sdk.vercel.ai/" target="_blank" rel="noreferrer">https://sdk.vercel.ai/</a></li><li>LangChain.js: <a href="https://js.langchain.com/" target="_blank" rel="noreferrer">https://js.langchain.com/</a></li><li>LLM Evaluation Frameworks: <a href="https://github.com/openai/evals" target="_blank" rel="noreferrer">https://github.com/openai/evals</a></li><li>Prompt Engineering Guide: <a href="https://www.promptingguide.ai/" target="_blank" rel="noreferrer">https://www.promptingguide.ai/</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Vercel AI SDK:</strong> Use for streaming, tool calling, and structured output in Next.js; provides React hooks for streaming UI</li><li><strong>Supabase for AI:</strong> Store conversation history, user preferences, and cached responses in Supabase tables</li><li><strong>Environment variables:</strong> Store API keys as <code>OPENAI_API_KEY</code>, <code>ANTHROPIC_API_KEY</code> etc. in <code>.env.local</code>; never expose to client</li><li><strong>Monitoring:</strong> Log token usage per request; set up alerts for cost anomalies; track latency percentiles</li><li><strong>Graceful degradation:</strong> When LLM services are unavailable, provide fallback responses or queue requests for later processing</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',37)])])}const h=t(i,[["render",o]]);export{p as __pageData,h as default};
